package com.example.g.activities;
import android.app.Activity;import android.content.Intent;import android.os.Bundle;import com.example.g.security.LockSession;
public class SplashActivity extends Activity{@Override protected void onCreate(Bundle b){super.onCreate(b);boolean done=getSharedPreferences("settings",0).getBoolean("setup_complete",false);Intent intent;if(!done)intent=new Intent(this,OnboardingActivity.class);else if(LockSession.isUnlocked())intent=new Intent(this,MainActivity.class);else intent=new Intent(this,LockActivity.class).putExtra("start_main",true);startActivity(intent);finish();}}
